INSERT INTO "db_meta" (rowid, "key", "value") VALUES (2, 'created_at', '2026-05-08 03:41');
INSERT INTO "db_meta" (rowid, "key", "value") VALUES (3, 'project', 'jordanelias/guidebook');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (1, 'D-0001', 'D-DOCT', 'DG-NON', NULL, 'THE PURPOSE OF THIS GUIDEBOOK IS TO GET PEOPLE TO ASK THE RIGHT QUESTIONS', 'THE PURPOSE OF THIS GUIDEBOOK IS TO GET PEOPLE TO ASK THE RIGHT QUESTIONS', 'THE PURPOSE OF THIS GUIDEBOOK IS TO GET PEOPLE TO ASK THE RIGHT QUESTIONS. This is the most important principle governing the entire project. The guidebook is not a prescription manual. It is not an authority on measurements. It does not dictate values that designers, policymakers, or practitioners must apply. It is a thinking tool that equips people to ask the right questions about how to design for accessibility depending on the circumstance. Measurements, ranges, and reference data exist to support this process — they serve the questions, not the other way around. Every item specification, every BPC synthesis, every piece of guidebook prose must be evaluated against this standard: does it help the reader ask better questions about this design element? Does it surface considerations they would not have encountered otherwise? Does it make them think more critically about the specific situation they face? When you know better, you do better. A designer who knows what questions to ask will produce a better outcome than one who does not — even without perfection, even without specialist input. The guidebook aims to raise the floor of understanding for everyone who touches the built environment.', '2026-04-24 23:38', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (2, 'D-0002', 'D-DOCT', 'DG-NON', NULL, 'Disability populations are not uniform', 'Disability populations are not uniform', 'Disability populations are not uniform. Every person within a population code has a unique experience and unique functional limitations, even where there is significant overlap with others who share the same condition. There are different ways to struggle with mobility, different ways to be blind, different ways to have MS, different ways to be autistic, different ways to have dementia, different ways to experience PTSD. There is no generic ideal for any population. Specifications provide ranges and starting points — not definitive answers. It is rare for a disability to be experienced in isolation; co-occurring conditions are the norm. Every item specification must acknowledge functional variability within the population and discuss how co-occurrence affects the design parameter, because that is the lived reality of the people the guidebook serves. Population codes are a high-level organizing principle: at Tier 0 they are comprehensive (mapping all considerations); at Tier 1 they offer insight (what to think about for a known population); at Tier 2 they step aside because a person is not defined by their disabilities — OT works bottom-up from functional impairments because everything must be uniquely tailored to the individual.', '2026-04-24 23:38', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (3, 'D-0003', 'D-DOCT', 'DG-NON', NULL, 'Three-Tier Design Hierarchy governs all specifications', 'Three-Tier Design Hierarchy governs all specifications', 'Three-Tier Design Hierarchy governs all specifications. Tier 0 = Universal Design / Code Compliance (population-agnostic, fixed values). Tier 1 = Population-Informed Inclusive Design (ranges; median as default). Tier 2 = Person-Specific Co-Design (OT assessment resolves position within Tier 1 range). DAR mandatory at all tiers.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (4, 'D-0004', 'D-DOCT', 'DG-NON', NULL, 'Evidence hierarchy is seven tiers', 'Evidence hierarchy is seven tiers', 'Evidence hierarchy is seven tiers. Tier 1 = OT intervention-tested clinical research; Co-1 = lived experience / participatory design (CRPD Art. 4.3, co-primary with Tier 1); Tier 2 = NGO/DPO/advocacy guidelines; Co-2 = OT professional body CPGs (CAOT, AOTA, RCOT, COTEC, WFOT); Tier 3 = systematic reviews and meta-analyses; Tier 4 = international standards with evidence basis; Tier 5 = national beyond-code frameworks; Tier 6 = statutory codes (reference baseline only). OT body guidelines = Tier 3 with [Tier 3 — CPG] marker. The evidence hierarchy determines what constitutes best practice. Codes (Tier 6) inform us in situations where nothing else can. Where higher-tier evidence exists, it governs.', '2026-03-19 19:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (5, 'D-0005', 'D-DOCT', 'DG-NON', NULL, 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for th...', 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for th...', 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for the disabled person. Best practice is determined by the evidence hierarchy — Tier 1 clinical research, Co-1 lived experience, Co-2 OT CPGs, Tier 3 systematic reviews — not by code consensus. Codes are Tier 6: the compliance floor, not the aspiration. Code consensus across jurisdictions establishes what most codes agree on; it does not establish what is most accommodating or most dignified. A BPC best_practice_synthesis that derives its value solely from code consensus is in error. The test: does this specification provide the most accommodating, dignified, usable condition the evidence supports — or does it merely reflect what codes agree on?', '2026-04-24 23:46', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 'D-0006', 'D-DOCT', 'DG-NON', NULL, 'Universal design is co-extensive with code compliance — the floor, not an aspiration', 'Universal design is co-extensive with code compliance — the floor, not an aspiration', 'Universal design is co-extensive with code compliance — the floor, not an aspiration. Inclusive design is the positive aspiration.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (7, 'D-0007', 'D-DOCT', 'DG-NON', NULL, 'Evidence specification markers', 'Evidence specification markers', 'Evidence specification markers. ● (filled circle) = evidence-based specification (Tier 1–6). ○ (empty circle) = inferred from clinical reasoning or expert consensus (gap disclosed). Every specification sentence carries either ● or ○. Unmarked = error.', '2026-03-20 21:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (8, 'D-0008', 'D-DOCT', 'DG-NON', NULL, 'BAR is not a main taxonomy code', 'BAR is not a main taxonomy code', 'BAR is not a main taxonomy code. Large body size is not a disability. BAR provisions belong in Supplementary Volume Supp. Part 4 only. No BAR reference, cross-reference, heading, or J-code is permitted in Volumes I–II. Delete on sight without replacement or pointer. Category J (J-01–J-05) is struck from Volume II Part 4.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (9, 'D-0009', 'D-DOCT', 'DG-NON', NULL, 'Specification ranges are not expressions of uncertainty', 'Specification ranges are not expressions of uncertainty', 'Specification ranges are not expressions of uncertainty. They are the designed-in bridge between Tier 1 and Tier 2. At Tier 1 use median. At Tier 2 resolve through co-design. Never write a range without specifying which end applies at which tier.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (10, 'D-0010', 'D-DOCT', 'DG-NON', NULL, 'Lived experience evidence is co-primary at Tier 3–4 where no clinical trial is feasible.', 'Lived experience evidence is co-primary at Tier 3–4 where no clinical trial is feasible.', 'Lived experience evidence is co-primary at Tier 3–4 where no clinical trial is feasible.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (11, 'D-0011', 'D-DOCT', 'DG-NON', NULL, 'VIS, DEAF, DBL are three distinct independent population codes', 'VIS, DEAF, DBL are three distinct independent population codes', 'VIS, DEAF, DBL are three distinct independent population codes. VIS/DEAF as a compound code is an error. DBL ≠ VIS + DEAF. See workplan-orchestrator §Population Codes for full canonical list.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (12, 'D-0012', 'D-DOCT', 'DG-NON', NULL, 'IntD (Intellectual Disability) is not a standalone population code', 'IntD (Intellectual Disability) is not a standalone population code', 'IntD (Intellectual Disability) is not a standalone population code. IntD provisions are proxied through DEM (wayfinding, cognitive simplicity) and NDV (sensory environment, Easy Read signage). No §2.12, no IntD matrix column, no IntD population code table entry. All IntD specifications carry THIN-BASE disclosure.', '2026-03-25 19:35', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (13, 'D-0013', 'D-DOCT', 'DG-NON', NULL, 'Biophilic Design (BIO-01–BIO-05) and Thermal Comfort (TC-01–TC-05) are in Appendices B and C respectively', 'Biophilic Design (BIO-01–BIO-05) and Thermal Comfort (TC-01–TC-05) are in Appendices B and C respectively', 'Biophilic Design (BIO-01–BIO-05) and Thermal Comfort (TC-01–TC-05) are in Appendices B and C respectively. Supplementary Resources A and B struck from Volume II body. No inline BIO- or TC- cross-references in Part 4 specs or room matrices. Single opening notice permitted in volume front matter.', '2026-03-18 20:10', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (14, 'D-0014', 'D-DOCT', 'DG-NON', NULL, 'The guidebook is a starting framework for professional judgment, not a substitute for it', 'The guidebook is a starting framework for professional judgment, not a substitute for it', 'The guidebook is a starting framework for professional judgment, not a substitute for it. Population-level specifications (Tier 0 and Tier 1) are necessary but insufficient. Part 1 must state this explicitly as a foundational principle.', '2026-03-26 16:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (15, 'D-0015', 'D-DOCT', 'DG-NON', NULL, 'Conflict resolution protocol (Part 5 and cross-synthesis escalation) operates at Tier 1 only', 'Conflict resolution protocol (Part 5 and cross-synthesis escalation) operates at Tier 1 only', 'Conflict resolution protocol (Part 5 and cross-synthesis escalation) operates at Tier 1 only. At Tier 2, conflict resolution is the domain of the OT and the individual through co-design. The guidebook''s Tier 2 role is to equip non-OT professionals with decision frameworks and structured approaches — not prescriptive answers.', '2026-03-26 16:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (16, 'D-0016', 'D-DOCT', 'DG-NON', NULL, 'The guidebook is an advocacy project, not an authority', 'The guidebook is an advocacy project, not an authority', 'The guidebook is an advocacy project, not an authority. It does not teach professional judgment, does not confer competence, and is not a registered body, standard-setting organization, or regulatory instrument. It is derived from comprehensive research and presents its findings in a multimodal manner to equip people who touch the built environment with better questions, better evidence, and better starting points. Readers apply their own professional judgment, informed by this material. The guidebook''s value is in the quality and comprehensiveness of the research it synthesizes and the accessibility of its presentation — not in any claim to authority over practice.', '2026-04-26 19:25', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (17, 'D-0017', 'D-SCHEMA', 'DG-NON', NULL, 'Item codes use bare category prefix only (A-01, B-06, etc.)', 'Item codes use bare category prefix only (A-01, B-06, etc.)', 'Item codes use bare category prefix only (A-01, B-06, etc.). No volume-part prefix (V2-P8-, V2-PV-, etc.). Item codes are Part-independent and do not change with renumbering.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Item Code System"]', '[]', 'Seeded from project-standards.md §Item Code System at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending. | Tier-C placeholder review 2026-05-02 (D-0120 batch): structural/mechanical operational rule retained at delegation/model_routing as seeded — these are not deliberative decisions but seeded-rule extractions, and per workplan/placeholder-review-triage.md §5.3 the legacy/none/none model_routing is appropriate to their character. Review pass marks them as audited rather than upgrading routing notation.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (18, 'D-0018', 'D-METH', 'DG-NON', NULL, 'All sources must be confirmed real', 'All sources must be confirmed real', 'All sources must be confirmed real. Unverified claims → [UNVERIFIED — DOI/URL required before publication]. citation-verifier defaults to PROVISIONAL mode.', '2026-03-15 00:00', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Citation and Evidence Standards"]', '[]', 'Seeded from project-standards.md §Citation and Evidence Standards at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (19, 'D-0019', 'D-METH', 'DG-NON', NULL, 'G-03 cites Levine 2023 (Human Factors, doi:10.1177/00187208211059860) AND Levine 2025 (JMIR, doi:10.2196/69442)', 'G-03 cites Levine 2023 (Human Factors, doi:10.1177/00187208211059860) AND Levine 2025 (JMIR, doi:10.2196/69442)', 'G-03 cites Levine 2023 (Human Factors, doi:10.1177/00187208211059860) AND Levine 2025 (JMIR, doi:10.2196/69442). Both required. Replace any "Levine 2024" with both.', '2026-03-17 21:30', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Citation and Evidence Standards"]', '[]', 'Seeded from project-standards.md §Citation and Evidence Standards at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (20, 'D-0020', 'D-METH', 'DG-NON', NULL, '2 failed independent searches → delete the unverifiable value (CLOSED-DELETED)', '2 failed independent searches → delete the unverifiable value (CLOSED-DELETED)', '2 failed independent searches → delete the unverifiable value (CLOSED-DELETED). Do not accumulate unresolvable UNVERIFIED flags.', '2026-03-18 19:10', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Citation and Evidence Standards"]', '[]', 'Seeded from project-standards.md §Citation and Evidence Standards at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
