INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (29, 'D-0029', 'D-METH', 'DG-NON', NULL, 'Part 7 conflict entries tagged [INTRA-INDIVIDUAL], [INTER-GROUP], or [BOTH]', 'Part 7 conflict entries tagged [INTRA-INDIVIDUAL], [INTER-GROUP], or [BOTH]', 'Part 7 conflict entries tagged [INTRA-INDIVIDUAL], [INTER-GROUP], or [BOTH]. Intra → Tier 2 OT resolution. Inter → Tier 0/1 architectural. Both → state both pathways.', '2026-03-28 21:30', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7CO-0003 + CO-0004 Structural Rules"]', '[]', 'Seeded from project-standards.md §CO-0003 + CO-0004 Structural Rules at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');
