INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (48, 'TERM-048', 'circulation route', 'Continuous route through a building used for horizontal movement between spaces', 'circulation', 'Element-level concept. The dimensional parameter is TERM-002 (corridor width); this term groups the route itself so retrieval catches corridor/hallway/circulation wording.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (49, 'TERM-049', 'acoustic absorption', 'Conversion of incident sound energy within a material rather than reflection back into the room', 'acoustic', 'Distinct from TERM-029 (sound masking, which ADDS sound) and TERM-007 (reverberation time, the room-level outcome absorption controls).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (50, 'TERM-050', 'speech intelligibility', 'Proportion of speech content correctly understood by a listener in a given acoustic environment', 'acoustic', 'Outcome measure that RT60 (TERM-007) and absorption (TERM-049) act upon.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (51, 'TERM-051', 'AAC (augmentative and alternative communication)', 'Methods and devices supplementing or replacing speech for expressive communication', 'communication', 'Environmental relevance: mounting, power, acoustics, lighting and dwell space for AAC use.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (52, 'TERM-052', 'rest point seating', 'Seating provided at intervals along a route to permit recovery without leaving the route', 'circulation', 'Links item E-10. Demand side is the sustained-exertion axis (TERM-043).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (53, 'TERM-053', 'fatigue and post-exertional malaise', 'Reduced capacity for sustained activity, including symptom exacerbation following exertion', 'medical', 'Symptom/mechanism term, NOT a population label — do not use as an umbrella population code (see governance/functional-taxonomy.md §3.3). Demand axis is TERM-043. Shares the de alias ''Belastungsintoleranz'' with axis TERM-043 (Sustained-exertion demand): this is the symptom, that is the demand layer.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T04:00:00Z', 'session_2026-07-25-synonym-grouping-fix');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (54, 'TERM-054', 'dysautonomia and orthostatic intolerance', 'Autonomic dysfunction producing symptoms on upright posture, including tachycardia and presyncope', 'medical', 'Environmental relevance: queueing, standing dwell time, seating availability, thermal load.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (55, 'TERM-055', 'chronic pain', 'Pain persisting beyond expected healing time, or continuous/recurrent pain affecting function', 'medical', 'Symptom term. The demand axis is TERM-040 (Pain-load demand); keep the two distinct.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (56, 'TERM-056', 'vestibular dysfunction', 'Impairment of the vestibular system affecting balance, gaze stability and spatial orientation', 'medical', 'Environmental relevance: floor pattern, visual flow, handrail continuity, lighting transitions. Demand axis is TERM-034 (Balance & postural demand).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (57, 'TERM-057', 'tremor and involuntary movement', 'Involuntary motor activity affecting precision, control and sustained positioning', 'medical', 'Environmental relevance: control targets, hardware forces, dwell distances. Demand axis is TERM-041 (Reach & manipulation).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (58, 'TERM-058', 'Changing Places toilet', 'Larger accessible toilet with height-adjustable adult bench, hoist and space for two assistants', 'bathroom', 'Links item E-15. Distinct from TERM-009 (accessible bathroom), which is the standard-provision term.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (59, 'TERM-059', 'visitability', 'Minimum dwelling accessibility permitting a disabled visitor to enter and use a ground-floor WC', 'methodology', 'A threshold standard, not full accessibility; distinct from TERM-068 (accessible housing).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (60, 'TERM-060', 'post-occupancy evaluation', 'Structured evaluation of a building in use against intended performance and occupant experience', 'methodology', 'Primary route by which lived-experience (Co-1) evidence re-enters the specification.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (61, 'TERM-061', 'headroom clearance', 'Unobstructed vertical dimension above a route or usable floor area', 'circulation', 'Vertical counterpart to TERM-002 (corridor width). Governs tall-stature envelope and hoist runs.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (62, 'TERM-062', 'body dimensions (anthropometrics)', 'Measured human body and reach dimensions used to derive spatial and reach provisions', 'methodology', 'Population-mode inputs. Per doctrine, population data informs but does not bound the individual.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (63, 'TERM-063', 'thermal comfort', 'Occupant satisfaction with the thermal environment, as distinct from measured air temperature', 'thermal', 'Links items F-07, F-08, K-05. Impairment side is TERM-015; demand axis is TERM-044.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (64, 'TERM-064', 'home adaptation grant', 'Public funding instrument financing accessibility modification of an existing dwelling', 'economics', 'Jurisdiction-specific instruments; named schemes are NARROWER aliases, not equivalents.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (65, 'TERM-065', 'accessibility economics', 'Cost, benefit and value analysis applied to accessibility provision', 'economics', 'Doctrine caution: economic framing supports advocacy but never substitutes for rights obligations.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (66, 'TERM-066', 'construction cost', 'Capital expenditure to build or modify, used to quantify the incremental cost of accessibility', 'economics', 'The incremental-cost figure, not total build cost, is the advocacy-relevant quantity.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (67, 'TERM-067', 'CRPD (Convention on the Rights of Persons with Disabilities)', 'UN human-rights treaty establishing accessibility and participation obligations', 'legal', 'Art. 9 (accessibility) and Art. 4.3 (participation) are the doctrinal anchors for Co-1 evidence.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (68, 'TERM-068', 'accessible housing', 'Dwelling designed or adapted for full use by disabled occupants, not merely visitable', 'housing', 'Full-use standard; TERM-059 (visitability) is the lower threshold.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (69, 'TERM-069', 'haptic affordance', 'Environmental feature conveying information or action possibility through touch', 'wayfinding', 'Broader than TERM-010 (TWSI), which is one standardised instance of a haptic affordance.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (70, 'TERM-070', 'school learning environment', 'Educational setting considered as a designed environment affecting access to learning', 'education', 'Links item A-18 (RT60 in learning and listening spaces).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (71, 'TERM-071', 'Design for Adaptable Readiness (DAR)', 'Designing so later accessibility adaptation is achievable without structural rework', 'methodology', 'Mandatory at all three Design Modes per governance/conceptual-model.md.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (72, 'TERM-072', 'toileting provision planning', 'Determining number, type and distribution of sanitary facilities across a building', 'bathroom', 'Quantity/distribution question. TERM-009 is the fixture-level accessible-WC term. Demand axis is TERM-036 (Toileting-proximity demand).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (73, 'TERM-073', 'neurodivergent sensory environment', 'Environmental sensory conditions considered from neurodivergent access requirements', 'sensory', 'References the existing NDV population codes; do NOT treat as a new population umbrella.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (74, 'TERM-074', 'withdrawal space and exit legibility', 'Somewhere to withdraw to that is not necessarily a room, plus a legible visible route out of it', 'sensory', 'Links items A-16, D-05, E-13. The designated room is TERM-012 (sensory room) — this term is the wider provision (alcove, recess, edge seating) plus the exit-legibility half. Retreat without a legible exit fails the arousal-safety axis (TERM-032).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T04:00:00Z', 'session_2026-07-25-synonym-grouping-fix');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (75, 'TERM-075', 'jurisdictional accessibility standards', 'Nationally or regionally binding accessibility requirements in codes and standards', 'legal', 'Regulatory stratum (T4-T6). Code convergence is NOT evidence — see governance/tier-system.md.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (76, 'TERM-076', 'multilingual evidence convergence', 'Agreement of findings across literatures in different languages', 'methodology', 'Methodology term. Convergence across LANGUAGES is not the same as convergence across CODES.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (77, 'TERM-077', 'cross-population design conflict', 'Situation where a provision benefiting one population creates a barrier for another', 'methodology', 'Conflicts are recorded and adjudicated, never silently averaged away.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (78, 'TERM-078', 'case study', 'Documented account of a specific built project or setting used as evidence or illustration', 'methodology', 'Evidence tier depends on method, not on the case-study label alone.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (79, 'TERM-079', 'mobility aid', 'Device supporting locomotion or transfer, setting the spatial envelope a route must accommodate', 'circulation', 'TERM-016 is the person (wheelchair user); this is the equipment. Keep person and device distinct.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (80, 'TERM-080', 'neurological impairment', 'Impairment arising from nervous-system conditions, with variable and often fluctuating presentation', 'medical', 'Named conditions are NARROWER aliases for retrieval only — never a population umbrella (see CLAUDE.md §10, work from axes).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (81, 'TERM-081', 'occupational therapy (OT)', 'Profession assessing person-occupation-environment fit and prescribing environmental adaptation', 'methodology', 'Co-2 evidence stratum: OT professional-body CPGs are co-primary with T2 (governance/tier-system.md). Also the Person-mode co-design route.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (82, 'TERM-082', 'biophilic design', 'Design incorporating nature, natural materials, daylight and views to support wellbeing', 'methodology', 'Claims here are frequently T3/grey — check tier before treating as evidence-based.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (83, 'TERM-083', 'trauma-informed design', 'Design reducing risk of re-traumatisation through control, sightlines, refuge and predictability', 'methodology', 'Overlaps the arousal-safety axis (TERM-032) and retreat provision (TERM-074).', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (84, 'TERM-084', 'laundry and utility room', 'Domestic utility space; appliance reach, transfer space and control access govern its usability', 'hardware', 'Residential DAR-relevant: appliance height and front-loading are adaptation-sensitive.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (85, 'TERM-085', 'fragrance-free policy', 'Operational and specification control of airborne fragrance and VOC exposure', 'sensory', 'Links items F-02, F-06. Operational policy and material specification act together; specification alone does not deliver a fragrance-free environment.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (86, 'TERM-086', 'cognitive accessibility and easy read', 'Making information and environments usable without high literacy or processing demand', 'communication', 'Demand axis is TERM-037 (Information-access demand). ''Intellectual disability'' and ''learning disability'' are retrieval aliases only — never a population umbrella.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (87, 'TERM-087', 'temporal accessibility and pacing', 'Time as an access dimension: dwell time, queueing, rest intervals and self-paced progression', 'methodology', 'Named in item E-03. A route meeting every dimensional rule can still be inaccessible if it cannot be traversed at the user''s own pace.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
INSERT INTO "terms" (rowid, "term_id", "canonical_en", "definition", "domain", "scope_note", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (88, 'TERM-088', 'upper limb function and grip', 'Hand, wrist and arm capability governing operable force, grip type and one-handed use', 'hardware', 'Demand axis is TERM-041 (Reach & manipulation). Operating force is TERM-005.', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping', '2026-07-25T00:00:00Z', 'session_2026-07-25-synonym-grouping');
