INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (1, 'AX-AMB', 'Ambulant movement', 'b770,b730', 'd450,d455,d460', 'Continuous walking, stairs, distance, gradients; floor-level living incl. floor-sitting, prostration, floor-to-standing transitions', 'E ramps/stairs/corridors, E-07 slip, E-10 rest seating; floor-level transfer provisions', 'ESTABLISHED', 'Re-merges with AX-WHM if evidence shows no parameter divergence between ambulant and wheeled movement', 'Alias source: MOB ambulant share (canonical MOB/AMB)', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (2, 'AX-WHM', 'Wheeled movement & transfer', 'b730,b710', 'd465,d420,d410', 'Turning, clearance, transfer geometry — independent and assisted (two-person, hoist)', 'E-01/E-12, G-04, turning circles, clear widths, hoist clearances', 'ESTABLISHED', 'Re-merges with AX-AMB if evidence shows no parameter divergence; transfer splits out per armature §5 if ratification item R6 so decides', 'Alias source: MOB wheeled share', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
