INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (4, 'AX-BAL', 'Balance & postural demand', 'b235,b240', 'd415,d410', '(a) fall-risk under gait/transfer load; (b) environments that precipitate dizziness: repeating pattern, specular floors, glazed edges at height, escalators, large uniform visual fields', 'handrails, E-07, C-03 (dual-purpose), stair geometry', 'STUB', 'Merges into AX-AMB if vestibular-slug research shows precipitant guidance fully reduces to existing fall-prevention parameters', 'Named in canon (armature §5 vestibular axis; NEU/PCS prose) yet operationally invisible: zero b-codes, zero slugs, zero searches in 19 tracked languages (EN-term caveat; §9.2 gate applies). Claims require tier-anchored sourcing before thresholds || FLAGGED 2026-07-24 (adversarial review): coverage_status=STUB and the "zero b-codes, zero slugs, zero searches" text above are STALE. Slug vestibular-balance-built-environment is ACTIVE with serves_axes=["AX-BAL"] and 21 source_slug_links (T1 REF-00911/00912/00913 handrail-recovery biomechanics; T2 REF-00792 Cochrane falls SR; T4 REF-00883 WHO APS15; T5 REF-00921 code dimensions), and evidence_cell_state already holds VES cells at B-08 and C-06 (both provisional, T3-only). Re-grade to PARTIAL is PROPOSED, not applied: axis coverage grading is a taxonomy decision and owner-gated.', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (5, 'AX-STA', 'Sustained-exertion demand', 'b455,b130', 'd230,d450,d455', 'Standing, queueing, distance without rest; grid/lift failure converting routes into exertion cliffs', 'E-10, F-05, seating provision; passive redundancy for grid intermittency', 'ESTABLISHED', 'Merges with AX-PAI into a single symptom-load axis if evidence shows no parameter divergence (nociceptive/central vs exertional)', 'Alias source: OFS', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (6, 'AX-PAI', 'Pain-load demand', 'b280', 'd410,d450,d640', 'Impact, vibration, pressure, cold; spans nociceptive AND centrally-sensitized pain — provisions must not assume load-avoidance alone suffices (fibromyalgia-type pain is not nociception-dominant)', 'floor-vibration, upholstered seating, hardware force', 'ESTABLISHED', 'Merges with AX-STA per the same condition, symmetrically', 'Alias source: PAIN; both feed pain-ofs slug', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
INSERT INTO "axes" (rowid, "axis_code", "name", "icf_b_anchors", "icf_d_anchors", "mechanism", "design_domains", "coverage_status", "falsification_condition", "notes", "created_at", "created_by_session") VALUES (7, 'AX-THR', 'Thermal demand', 'b550', 'd230', 'Heat/cold exposure for impaired thermoregulation — via conditioning and passive means (shading, mass, ventilation) where grids are intermittent', 'TC-01..05, H-02; passive-first options', 'PARTIAL', 'Dissolves into item-level thermal specs if no population-differentiated thresholds survive evidence review', 'Names the axis scattered across MS/SCI/OFS diagnoses', '2026-07-21T22:45:00Z', 'session_2026-07-21-taxonomy-execution');
