INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (1, 'A-NOSIGHT', 'perceiving', 'Be perceivable and operable without sight; text alternatives, audio description, braille, logical reading order; never colour alone as a carrier of meaning.', 'blindness, low vision, colour vision deficiency, temporary eye injury, glare', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (2, 'A-NOSOUND', 'perceiving', 'Never carry meaning in sound alone; captions, transcripts, visual alerts, sign-language provision where it is the user''s language.', 'Deaf, hard of hearing, late-deafened, ear infection, loud/silent environments', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (3, 'A-TACTILE', 'perceiving', 'Offer touch as a first-class channel, not a fallback; tactile signage/maps, hand-under-hand guidance, protactile-aware interpreting, physical landmarks.', 'DeafBlind (Protactile) — not A-NOSIGHT + A-NOSOUND', NULL, 'access-taxonomy v0.1', 'No exact axis: DeafBlind access is distinct. Genuine coverage gap vs the axis layer.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (4, 'A-STABLE', 'perceiving', 'Hold the visual reference still; no auto-playing motion/parallax; handrails, signalled level changes, rest points.', 'vestibular disorders, migraine, motion sensitivity, post-concussion, pregnancy', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (5, 'A-NOSPEECH', 'communicating', 'Never require speech or voice; text alternatives to calls, AAC-compatible interaction, no voice-only auth, time to compose.', 'aphasia, dysarthria, stammering, non-speaking people, AAC users, laryngitis, L2 users', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (6, 'A-PLAIN', 'communicating', 'Use plain, predictable language and structure; controlled reading level, no unexplained jargon, consistent patterns, glossary where terms are load-bearing.', 'dyslexia, intellectual disability, dementia, brain injury, distraction, L2 users', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (7, 'A-REACH', 'operating', 'Be physically reachable; step-free routes, seated-height controls, doorway/turning clearance, one-handed operation, no simultaneous-input requirement.', 'wheelchair users, ambulatory wheelchair users, cane/crutch users, limb difference, carrying a child', NULL, 'access-taxonomy v0.1', 'Spans three axes (REA/WHM/AMB).', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (8, 'A-PRECISION', 'operating', 'Tolerate imprecise input; large targets, generous spacing, no fine-motor/drag-only interaction, timing that tolerates tremor and overshoot.', 'tremor, dystonia, Parkinson''s, arthritis, neuropathy, cold hands', NULL, 'access-taxonomy v0.1', 'No dedicated motor-precision axis — gap. Pairs with a MOVE population if adopted.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (9, 'A-AT', 'operating', 'Work with assistive technology; programmatically-determinable structure, standard controls, no custom widgets without full semantics.', 'screen readers, magnification, switch access, voice control, alternative keyboards', NULL, 'access-taxonomy v0.1', 'Conformance/artifact property (WCAG Robust). Digital — may be out of built-environment scope; flagged for owner decision.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (10, 'A-SELFCARE', 'operating', 'Support personal care and daily tasks; accessible toilets and changing places, operable fixtures, privacy, dignity, no dependence on a helper being present.', 'bathing, dressing, toileting, eating', NULL, 'access-taxonomy v0.1', 'Broader than AX-CNT (toileting only): adds washing/dressing/eating (d510/d540/d550).', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (11, 'A-LOWLOAD', 'pacing', 'Keep memory and attention demand low; chunking, save/resume, no reliance on recall across steps, undo, progress visible.', 'ADHD, dementia, brain injury, brain fog, intellectual disability, anyone interrupted', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (12, 'A-TIME', 'pacing', 'Impose no time pressure; no session timeouts without extension, no timed inputs, no penalty for slowness.', 'slow processing, motor delay, AAC use, screen-reader navigation, translation, distraction', NULL, 'access-taxonomy v0.1', 'No dedicated time-pressure axis — cuts across STA/COG. Gap.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (13, 'A-EFFORT', 'pacing', 'Cost little energy; short paths, seated options, save/resume, rest points, no forced continuous sessions, no penalty for stopping.', 'energy-limiting conditions, ME/CFS, Long COVID, POTS, MS fatigue, pain, cardiac/respiratory, older adults, recovery', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (14, 'A-STIMULUS', 'environment_safety', 'Let the user turn it down; reduce default stimulus density; mute, dim, reduce-motion, hide decorative content.', 'autistic people, sensory processing differences, migraine, post-concussion, PTSD, open-plan offices', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (15, 'A-TRIGGER', 'environment_safety', 'Not emit the trigger; under flash thresholds; fragrance-free; material/ingredient disclosure; no strobe.', 'photosensitive epilepsy, MCAS, chemical sensitivity, migraine', 'safety-critical', 'access-taxonomy v0.1', 'Spans SPR (photic) + CHM (airborne). Nearly always safety-critical.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (16, 'A-CALM', 'environment_safety', 'Not manufacture pressure; no artificial urgency or dark patterns, forgiving of errors, private by default, calm defaults, clear exit.', 'anxiety, PTSD, psychiatric distress, autistic people, anyone under stress', NULL, 'access-taxonomy v0.1', NULL, '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_needs" (rowid, "need_code", "family", "design_obligation", "absorbs", "typical_stakes", "source_version", "notes", "created_at", "created_by_session") VALUES (17, 'A-SIZE', 'environment_safety', 'Fit the range of bodies present; reach ranges at short and tall ends, seat width and weight rating, adjustable heights, clearance. Frame as the environment being wrongly normed to an average body, never as bodies deviating.', 'little people, tall people, fat people, pregnancy, children, wheelchair seating height', NULL, 'access-taxonomy v0.1', 'The body-size link; the design home for the body-size population group.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
