INSERT INTO "access_need_icf" (rowid, "need_code", "icf_code", "icf_type", "confidence", "note", "created_at", "created_by_session") VALUES (31, 'A-TIME', 'b164', 'b', 'confirmed', 'higher-level cognitive functions: time management, planning & sequencing (verified WHO/ICF 2026-07-23). Rationale (owner 2026-07-23): brain fog impairs organizing time and retaining the sequence of actions, so tasks run slower as people work to hold onto intent -> the environment must impose no time pressure. No axis carries it.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
