INSERT INTO "access_duration" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (1, 'permanent', 'A lasting characteristic of the person''s relationship to the barrier.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_duration" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (2, 'temporary', 'Time-limited (injury, recovery, pregnancy, treatment).', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_duration" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (3, 'situational', 'Context-induced for anyone (loud room, bright sun, carrying a child). A non-empty situational relevance is why there is no ALL code.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_stakes" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (1, 'safety-critical', 'Harm if violated.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_stakes" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (2, 'exclusion', 'Locks people out.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "access_stakes" (rowid, "code", "definition", "created_at", "created_by_session") VALUES (3, 'friction', 'Degrades the experience.', '2026-07-23T00:00:00Z', 'session_2026-07-23-access-needs-integration');
INSERT INTO "life_stage_modifiers" (rowid, "code", "label", "definition", "created_at", "created_by_session") VALUES (1, 'SEN', 'older adults; older disabled people', 'Life-stage modifier, orthogonal to all populations and needs. Many members reject "disabled" as a self-description while having substantial access needs.', '2026-07-23T00:00:00Z', 'session_2026-07-23-population-schema-replace');
INSERT INTO "life_stage_modifiers" (rowid, "code", "label", "definition", "created_at", "created_by_session") VALUES (2, 'CHD', 'disabled children; children with disabilities', 'Life-stage modifier, orthogonal. Convention rests on parent-led/professional organizations more than children''s own stated preference — weaker evidence than elsewhere.', '2026-07-23T00:00:00Z', 'session_2026-07-23-population-schema-replace');
