INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (65, 'REF-00073', NULL, 'https://www.resna.org/sites/default/files/legacy/conference/proceedings/2006/Research/Outcomes/Steinfeld.html', NULL, NULL, NULL, NULL, 'UDI wheelchair dimensions research — anthropometric + spatial dimensions study informing universal-design codes; tested wheelchair + scooter turning space requirements (e.g., 180° turn requiring 1925mm = 75.8in vs ANSI A117.1 baseline); cited in Steinfeld E, Maisel J, Feathers D (2005) "Standards and anthropometry for wheeled mobility" Buffalo NY: IDEA Center; foundational evidence for ICC/ANSI A117.1 (1998), CSA B651-04 (Canada), BS 8300:2001 (UK), AS 1428.2-1992 (AU) cross-jurisdictional comparison. Lead author Laurie Ringaert currently on Accessibility Standards Canada Board of Directors; owner Change Weavers Consulting (Winnipeg/Nanaimo); 30+ years accessibility research; previously led Universal Design Institute University of Manitoba + Centre for Universal Design NCSU.', 'NO-MATCH', NULL, NULL, 'corpus-pre-reset-2026-08-06');
INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (66, 'REF-00074', NULL, 'https://www.bca.gov.sg/Professionals/IBuildSG/others/Accessibility_Code_2019.pdf', NULL, NULL, NULL, NULL, 'BCA Code on Accessibility in the Built Environment 2025 — successor to 2019 edition; mandated by Singapore Building Control Act (Cap. 29) + Building Control Regulations; applies to all new and substantially renovated buildings; covers wheelchair access, ambulant disability, vision impairment, hearing impairment, neurodivergent/cognitive accessibility. Companion: BCA Universal Design Mark (UD Mark, voluntary certification scheme since 2008); Singapore Enabling Masterplan 2030; Land Transport Authority (LTA) Code on Barrier-Free Accessibility 2020.', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
