INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (77, 'REF-00085', NULL, 'https://hogeweyk.dementiavillage.com/', NULL, NULL, NULL, NULL, 'De Hogeweyk — first dementia village globally; Weesp NL (~17km Amsterdam); opened 2009 (transformed from traditional nursing home); 23 apartments + outpatient unit + community centre + restaurants + shops + theatre + barber shop + green spaces; ~169 residents in 6-7 person small-household groupings by familiar lifestyle/cultural background; ~40% wheelchair-using residents; palliative care team including geriatricians on staff; average dying period ~4 days; underlying Dutch Wlz (Wet langdurige zorg). POE-related synthesis evidence: CDA-AMC Dementia Villages review (Eloy van Hal personal communication 2019-05-12); Mendes A, Vasconcelos M et al. 2020 IPA International Psychogeriatrics congress abstract 440 "Dementia villages: rethinking dementia care" (PubMed PsycINFO Web-of-Science scoping); Cambridge Core. Companion: ScienceDirect 2021 mixed-methods scoping review S1041610224040250 (75-article corpus, 3 innovative-design types).', 'NO-MATCH', NULL, NULL, 'corpus-pre-reset-2026-08-06');
