INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (262, 'REF-00286', NULL, 'https://www.umcommunities.org/avandell/', NULL, NULL, NULL, NULL, 'Avandell — first U.S. dementia village; Holmdel NJ (Monmouth County); 18 acres; 15 seven-bedroom houses (cottages); 105 residents grouped by shared values (music/sports/art); Town Center with grocery store + bistro + community room + neurocognitive clinic + resource hub open to public; landscaped meadows + buffers; farmhouse aesthetic for rural setting; unobtrusive residential-style secure perimeter. Inspired by De Hogeweyk (Carlson visited 2017). Featured in The New York Times July 2023. Owner Larry Carlson former UMC President+CEO (11 years; 45+ years senior-living industry). Funding: private-pay (~$12,000/month projection), departure from European socialized-medicine model. Still in zoning process as of April 2024.', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (263, 'REF-00287', NULL, 'https://www.iglobenews.org/living-with-dementia/', NULL, NULL, NULL, NULL, 'iGlobenews article "Living with Dementia in Dignity: The Dutch Hogeweyk Concept" published 3 April 2025 — first dementia village originated 1992 by Yvonne van Amerongen + Jannette Spiering (Hogeweyk management team); innovative concept co-developed for severe dementia; Eloy van Hal joined as co-creator and now leads The Hogeweyk Care Concept knowledge-transfer programme. ~4 acres; ~169 residents (or 152 per FT 2019 reporting; 150-169 range across sources); 23 houses; 6-7 residents per household. Critiques: high initial investment, policy-support needs, staffing concerns, "happy fantasy world" critique. Counter-evidence: same per-resident Dutch nursing-home budget; antipsychotic use 1-in-10 vs 1-in-4 standard NL dementia care; lower staff turnover suggested. Companion: REF-00085 De Hogeweyk POE (different evidence package).', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
