INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (275, 'REF-00299', NULL, 'https://www.regjeringen.no/contentassets/565cb331b0ee4bb4b997157a543a51d4/the-governments-action-plan-for-universal-design-20152019_q-1233-e.pdf', NULL, NULL, NULL, NULL, 'Government''s Action Plan for Universal Design 2015–2019 — 47 measures across ICT, buildings/outdoor areas, transport, plan/design, welfare technology; underlying UNCRPD ratified by Norway 2013; Likestillings- og diskrimineringsloven (Equality and Anti-Discrimination Act 2017 § 17 + § 28-30); Plan- og bygningsloven; Forskrift om universell utforming av IKT (UU-tilsynet); ATB-forskriften. Benefit-cost analyses framework formalised at UD2024 conference (Sept 2024) — Vista Analyse + Bufdir + Norsk Regnesentral (NR) + Oslo Economics methods; Andresen JR + Sveen AW (Bufdir) "Instructions for Official Studies of Central Government Measures"; Lindberg L + Amilon A "Universal design and socio-economic analysis: A mapping of analyses and literature"; Harsheim IG (Oslo Economics) "Socio-economic analysis of additional obligations for universal design of ICT in the workplace".', 'NO-MATCH', NULL, NULL, 'corpus-pre-reset-2026-08-06');
INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (276, 'REF-00300', NULL, 'https://hcma.ca/assets/rick-hansen-foundation-accessibility-certification-retrofits-and-upgrades-cost-study/', NULL, NULL, NULL, NULL, 'RHFAC Retrofits and Upgrades Cost Study — published January 2024 (publication date 2024-01-05); 10 RHFAC-rated office towers + 10 RHFAC-rated schools (BC + Ontario, built 1974-2019); RHFAC program version 3.0 methodology. Findings: RHFAC Gold achievable for <0.5% of replacement cost in an office tower; <1.5% in a K-12 school; $1.50/sf offices + $9.00/sf schools (gross floor area); no-cost upgrades (furniture relocation), minimal-cost upgrades (assistive listening systems, braille signage, colour-contrast signage, fixture-height adjustment), higher-cost upgrades (fire alarm systems, accessible kitchens, universal washrooms). Companion: 2020 RHFAC Cost Comparison Feasibility Study; underlying CAN-ASC standards + provincial building codes (NBC 2015 + OBC 2018); Accessible Canada Act (S.C. 2019, c. 10) + Accessibility for Manitobans Act + AODA (Ontario).', NULL, 'RESOLVED', '2026-05-13T01:33:33Z', 'corpus-pre-reset-2026-08-06');
