INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (280, 'REF-00304', NULL, 'https://adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities', NULL, NULL, NULL, NULL, 'ADA National Network "Top ADA Frequently Asked Questions" page (adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities) — states: "The cost of incorporating accessibility features in new construction is less than one percent of construction costs. This is a small price in relation to the economic benefits to be derived from full accessibility in the future, such as increased employment and consumer spending." Companion: ada.gov + access-board.gov; underlying ADA Title III + 2010 ADA Standards for Accessible Design. Source for the widely-cited <1% new-build accessibility cost premium claim.', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
