INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (285, 'REF-00309', NULL, 'https://adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities', NULL, NULL, NULL, NULL, 'ADA National Network "Top ADA Frequently Asked Questions" page (adata.org/faq/it-expensive-make-all-newly-constructed-places-public-accommodation-and-commercial-facilities) — states: "The cost of incorporating accessibility features in new construction is less than one percent of construction costs. This is a small price in relation to the economic benefits to be derived from full accessibility in the future, such as increased employment and consumer spending." Companion: ada.gov + access-board.gov; underlying ADA Title III + 2010 ADA Standards for Accessible Design. Source for the widely-cited <1% new-build accessibility cost premium claim.', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (286, 'REF-00310', NULL, 'https://portal.research.lu.se/en/publications/universal-design-in-practice-understanding-implementation-and-co-/', NULL, NULL, NULL, NULL, 'Lund University PhD dissertation — qualitative research methodology with 55 participants across diverse backgrounds; participant observation in 3 Swedish municipalities; 3 urban-development projects studied; qualitative content analysis; key findings: multifaceted understanding of Universal Design (ethical principle for inclusion of diversity, vision of an equal society, unification of policy perspectives); emphasizes flexibility, predictability, personalized support; identifies tensions between municipality + local disability organizations on role/user-perspective interpretation; develops co-creative working-method model. Companion: Swedish PBL (Plan- och bygglag) + BBR (Boverkets byggregler) + UNCRPD ratification framework.', 'NO-MATCH', NULL, NULL, 'corpus-pre-reset-2026-08-06');
INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (287, 'REF-00311', NULL, 'https://www.oecd.org/en/data/datasets/oecd-affordable-housing-database.html', NULL, NULL, NULL, NULL, 'OECD Affordable Housing Database (AHD) — oe.cd/ahd; underlying data source: OECD Questionnaire on Affordable and Social Housing (QuASH), rounds 2016, 2019, 2021, 2023; covers PH1-PH7 indicators: housing market conditions (HC1-HC2), housing allowances (PH3), social rental (PH4), affordable housing programmes (PH5), rental regulation (PH6), financing improvements + regeneration (PH7). 2020 snapshot referenced in Society at a Glance 2024 (10th biennial edition).', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
