INSERT INTO "source_locators" (rowid, "ref_id", "doi", "url", "pmid", "pmcid", "isbn", "issn", "standard_number", "doi_resolution_outcome", "url_resolution_outcome", "url_last_fetched", "recovered_from") VALUES (831, 'REF-VERIFIED-007', NULL, 'https://www.fia.uk.com/static/fb69bc48-05f2-4517-a2fb64ad48b5319b/Guidance-Document-Fire-alarm-considerations-for-people-with-sensory-sensitivities-05-22.pdf', NULL, NULL, NULL, NULL, 'FIA Guidance Document GD-05-22 — published May 2022; addresses gap in BS 5839-1 Code of practice for fire detection and fire alarm systems (which addresses hearing impairment + photosensitive epilepsy only, not other sensory sensitivities like autism); 700,000 UK persons with autism spectrum disorder + sensory sensitivities affected; ~1,500 special schools in UK + special needs units in mainstream schools + day centres; recommendations: attention-drawing signals less startling than continuous alarm (BS 5839-8:2013 Clause 20 attention-drawing signal, 2-tone 550-825Hz alternating no more than every 0.5s fading in/out, meeting-chime-style softer sound); VAD (Visual Alarm Device) selectable power; pre-warned tests; ear defenders; relocation near final exit; staff-only EN54-23 VID rather than building-wide VAD; bedroom-paired smoke alarm/sounder. Underlying Equality Act 2010 + Clause 7 of BS 5839-1.', NULL, NULL, NULL, 'corpus-pre-reset-2026-08-06');
