CREATE VIEW v_coverage_priority AS
SELECT
    s.slug,
    ljm.jurisdiction,
    ljm.language,
    ljm.role,
    ( (CASE ljm.role WHEN 'PRIMARY' THEN 3 ELSE 1 END)
      + (CASE WHEN (SELECT COUNT(*) FROM search_executions se2
                    WHERE se2.slug = s.slug AND se2.deferred_reason IS NULL) = 0
              THEN 2 ELSE 0 END)
    ) AS priority_score,
    (SELECT COUNT(*) FROM search_executions se3
     WHERE se3.slug = s.slug AND se3.deferred_reason IS NULL) AS slug_searches
FROM slugs s
JOIN lang_jur_map ljm            -- CROSS JOIN: every in-scope slug x every required (lang,jur)
WHERE s.status IN ('ACTIVE', 'STUB')
  AND NOT EXISTS (
      SELECT 1 FROM search_executions se
      WHERE se.slug = s.slug
        AND se.jurisdiction = ljm.jurisdiction
        AND se.language = ljm.language
  );
CREATE VIEW v_pmp_latest_walk AS
SELECT
    item_code,
    slug,
    walk_id,
    MAX(created_at) AS walk_completed_at,
    SUM(CASE WHEN phase IN (
            'outer-pass-1st','outer-pass-2nd',
            'refinement-pass-1st','refinement-pass-2nd'
        ) THEN 1 ELSE 0 END) AS supported_steps,
    SUM(CASE WHEN phase IN (
            'outer-stop','refinement-stop'
        ) THEN 1 ELSE 0 END) AS terminator_steps
FROM spec_value_probes
GROUP BY item_code, slug, walk_id;
CREATE VIEW v_root_id_conflicts AS
    SELECT 'ref_id_has_multiple_root_ids' AS conflict_type,
           root_ref_id AS conflict_key,
           COUNT(DISTINCT root_id) AS distinct_count
    FROM source_value_extractions
    WHERE root_ref_id IS NOT NULL AND root_id IS NOT NULL
    GROUP BY root_ref_id HAVING COUNT(DISTINCT root_id) > 1
    UNION ALL
    SELECT 'root_id_spans_multiple_ref_ids' AS conflict_type,
           root_id AS conflict_key,
           COUNT(DISTINCT root_ref_id) AS distinct_count
    FROM source_value_extractions
    WHERE root_ref_id IS NOT NULL AND root_id IS NOT NULL
    GROUP BY root_id HAVING COUNT(DISTINCT root_ref_id) > 1;
CREATE VIEW v_unregistered_roots AS
    SELECT sve.extraction_id, sve.slug, sve.parameter, sve.root_id
    FROM source_value_extractions sve
    WHERE sve.root_id IS NOT NULL
      AND sve.root_ref_id IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM external_root_registry err
          WHERE err.root_id = sve.root_id);
CREATE VIEW v_value_independence AS
    SELECT COALESCE(parameter_canonical, parameter) AS parameter,
           population_code,
           COUNT(DISTINCT COALESCE(root_ref_id, root_id)) AS independent_root_count
    FROM source_value_extractions
    WHERE root_type IN ('measurement_primary', 'participatory_finding',
                        'derived_calculation')
      AND (root_ref_id IS NOT NULL
           OR root_id IN (SELECT root_id FROM external_root_registry))
    GROUP BY COALESCE(parameter_canonical, parameter), population_code;
CREATE INDEX idx_room_items_item ON room_items(item_code);
CREATE VIEW v_item_provenance AS
SELECT
    i.item_code,
    i.name                      AS item_name,
    i.category                  AS item_category,
    ecs.specification_id,
    ecs.population_code,
    ecs.state                   AS cell_state,
    ecs.tier_basis,
    ecs.regulatory_stratum_only,
    csl.role                    AS source_role,
    es.ref_id,
    es.pub_title,
    es.author_display,
    es.pub_year,
    es.tier                     AS source_tier,
    es.evidence_type,
    es.verification_status,
    es.jurisdiction
FROM items i
JOIN "specifications" ecs ON ecs.item_code = i.item_code
JOIN "specification_source_links"   csl ON csl.specification_id   = ecs.specification_id
JOIN evidence_sources    es  ON es.ref_id     = csl.ref_id;
CREATE VIEW v_source_reach AS
SELECT
    es.ref_id,
    es.pub_title,
    es.tier                     AS source_tier,
    es.verification_status,
    ecs.specification_id,
    ecs.item_code,
    i.name                      AS item_name,
    ecs.population_code,
    ecs.state                   AS cell_state,
    (SELECT GROUP_CONCAT(ssl.slug, '; ')
       FROM source_slug_links ssl
      WHERE ssl.ref_id = es.ref_id)  AS admitted_under_slugs
FROM evidence_sources es
JOIN "specification_source_links"   csl ON csl.ref_id  = es.ref_id
JOIN "specifications" ecs ON ecs.specification_id = csl.specification_id
JOIN items i                 ON i.item_code = ecs.item_code;
CREATE VIEW v_source_reach_all AS
SELECT
    es.ref_id,
    es.pub_title,
    es.tier                     AS source_tier,
    es.verification_status,
    CASE WHEN ecs.specification_id IS NULL THEN 0 ELSE 1 END AS reaches,
    ecs.specification_id,
    ecs.item_code,
    i.name                      AS item_name,
    ecs.population_code,
    ecs.state                   AS cell_state,
    (SELECT GROUP_CONCAT(ssl.slug, '; ')
       FROM source_slug_links ssl
      WHERE ssl.ref_id = es.ref_id)  AS admitted_under_slugs
FROM evidence_sources es
LEFT JOIN "specification_source_links"   csl ON csl.ref_id  = es.ref_id
LEFT JOIN "specifications" ecs ON ecs.specification_id = csl.specification_id
LEFT JOIN items i                 ON i.item_code = ecs.item_code;
CREATE INDEX idx_evidence_sources_standing
  ON evidence_sources(verification_status, verification_disposition);
CREATE INDEX idx_search_admissions_ref ON search_admissions(ref_id);
CREATE VIEW v_source_admission AS
SELECT
    es.ref_id,
    es.pub_title,
    es.tier                     AS source_tier,
    es.evidence_type,
    es.verification_status,
    es.verification_disposition,
    se.exec_id,
    se.slug                     AS admitted_under_slug,
    se.query_text,
    se.engine,
    se.language,
    se.jurisdiction             AS search_jurisdiction,
    se.depth_method,
    se.mining_direction,
    se.target_tier,
    se.backfill                 AS search_was_backfilled,
    se.session                  AS admitting_session,
    se.executed_at              AS admitted_at
FROM evidence_sources es
JOIN search_admissions sa ON sa.ref_id  = es.ref_id
JOIN search_executions se ON se.exec_id = sa.exec_id;
CREATE INDEX idx_sve_item ON source_value_extractions(item_code);
CREATE VIEW v_item_extractions AS
SELECT
    i.item_code,
    i.name                      AS item_name,
    i.category                  AS item_category,
    sve.extraction_id,
    sve.slug,
    sve.parameter,
    sve.parameter_canonical,
    sve.population_code,
    sve.jurisdiction,
    sve.claim_type,
    sve.claimed_value,
    sve.claimed_unit,
    sve.extraction_status,
    sve.extraction_method,
    sve.root_id,
    sve.root_type,
    sve.root_ref_id,
    sve.contested,
    sve.ref_id,
    es.tier                     AS source_tier,
    es.verification_status,
    sve.promoted_to_rdc_id
FROM items i
JOIN source_value_extractions sve ON sve.item_code = i.item_code
LEFT JOIN evidence_sources es     ON es.ref_id     = sve.ref_id;
